def binary_search(items, target):
    """Return the index of target in the sorted list items, or -1 if absent.
    Must run in O(log n)."""
    left, right = 0, len(items) - 1
    while left <= right:
        mid = (left + right) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
